-- All identities and records in this file are synthetic and local-only.
CREATE FUNCTION test.validate_campaign() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF new.kind='campaign' AND new.data->>'type'='importada' THEN PERFORM rotamapa_private.check_imported_campaign(new.user_id,new.portfolio_id,new.data);END IF;RETURN new;END$$;
CREATE TRIGGER check_campaign BEFORE INSERT OR UPDATE ON public.rotamapa_commerce_items FOR EACH ROW EXECUTE FUNCTION test.validate_campaign();
CREATE FUNCTION test.rejects(value jsonb,label text) RETURNS void LANGUAGE plpgsql AS $$DECLARE rejected boolean:=false;id uuid:=gen_random_uuid();BEGIN value:=jsonb_set(value,'{id}',to_jsonb(id::text));BEGIN INSERT INTO public.rotamapa_commerce_items VALUES(auth.uid(),public.rotamapa_current_portfolio(),id,'campaign',value);EXCEPTION WHEN OTHERS THEN rejected:=true;END;PERFORM test.ensure(rejected,label);END$$;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA test TO authenticated;
INSERT INTO public.rotamapa_commerce_items VALUES('00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000002','product','{"id":"10000000-0000-4000-8000-000000000002","kind":"product","name":"Produto de outra conta","priceCents":2000}');
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
SELECT set_config('test.portfolio','00000000-0000-4000-8000-000000000010',false);
INSERT INTO public.rotamapa_commerce_items VALUES(auth.uid(),public.rotamapa_current_portfolio(),'10000000-0000-4000-8000-000000000001','product','{"id":"10000000-0000-4000-8000-000000000001","kind":"product","name":"Produto sintético","priceCents":2000}');
CREATE TEMP TABLE source_fixture AS SELECT jsonb_build_object('campaignFamily','dia_d','entries',jsonb_build_array(jsonb_build_object('productId','10000000-0000-4000-8000-000000000001','name','Produto sintético','minimum',6,'priceCents',null,'discountBps',1000,'validFrom','2026-11-18','validTo','2026-11-18','region','RN','stock','30','startTime','08:00','endTime','18:00','restrictions',''))) AS data;
INSERT INTO public.rotamapa_library_items SELECT auth.uid(),public.rotamapa_current_portfolio(),repeat('a',64),'campaigns',repeat('b',64),data FROM source_fixture;
CREATE TEMP TABLE source_campaign AS SELECT jsonb_build_object('id','20000000-0000-4000-8000-000000000001','kind','campaign','type','importada','name','Dia D original','productId','10000000-0000-4000-8000-000000000001','startDate','2026-11-18','endDate','2026-11-18','tiers','[]'::jsonb,'imported',jsonb_build_object('version',1,'documentId',repeat('a',64),'sourceHash',repeat('b',64),'entries',data->'entries')) AS data FROM source_fixture;
INSERT INTO public.rotamapa_commerce_items SELECT auth.uid(),public.rotamapa_current_portfolio(),(data->>'id')::uuid,'campaign',data FROM source_campaign;
CREATE TEMP TABLE copy_campaign AS SELECT jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{id}','"20000000-0000-4000-8000-000000000002"'),'{startDate}','"2026-11-20"'),'{endDate}','"2026-11-20"'),'{imported,entries}',jsonb_build_array(jsonb_set(jsonb_set(jsonb_set(data#>'{imported,entries,0}','{validFrom}','"2026-11-20"'),'{validTo}','"2026-11-20"'),'{discountBps}','1500'))),'{copiedFrom}',jsonb_build_object('sourceId',repeat('a',64),'sourceDate','2026-11-18')) AS data FROM source_campaign;
INSERT INTO public.rotamapa_commerce_items SELECT auth.uid(),public.rotamapa_current_portfolio(),(data->>'id')::uuid,'campaign',data FROM copy_campaign;
SELECT test.ensure((SELECT count(*)=2 FROM public.rotamapa_commerce_items WHERE kind='campaign'),'original and daily copy inserted through the validator');
SELECT test.ensure((SELECT i.data=f.data FROM public.rotamapa_library_items i CROSS JOIN source_fixture f),'source document unchanged');
SELECT test.ensure((SELECT i.data=f.data FROM public.rotamapa_commerce_items i CROSS JOIN source_campaign f WHERE i.id=(f.data->>'id')::uuid),'source campaign unchanged');
SELECT test.ensure((rotamapa_private.imported_campaign_line('{"priceCents":2000}',6,(SELECT data FROM copy_campaign),'2026-11-20','{"region":"RN","time":"10:00"}')->>'unitCents')::int=1700,'copy uses its new date and edited percentage');
SELECT test.ensure((rotamapa_private.imported_campaign_line('{"priceCents":2000}',6,(SELECT data FROM copy_campaign),'2026-11-18','{"region":"RN","time":"10:00"}')->>'unitCents')::int=2000,'copy cannot apply on original date');
SELECT test.ensure((rotamapa_private.imported_campaign_line('{"priceCents":2000}',31,(SELECT data FROM copy_campaign),'2026-11-20','{"region":"RN","time":"10:00"}')->>'unitCents')::int=2000,'stock still enforced');
SELECT test.ensure((rotamapa_private.imported_campaign_line('{"priceCents":2000}',6,(SELECT data FROM copy_campaign),'2026-11-20','{"region":"PB","time":"10:00"}')->>'unitCents')::int=2000,'region still enforced');
SELECT test.ensure((rotamapa_private.imported_campaign_line('{"priceCents":2000}',6,(SELECT data FROM copy_campaign),'2026-11-20','{"region":"RN","time":"20:00"}')->>'unitCents')::int=2000,'time still enforced');
SELECT test.ensure((rotamapa_private.imported_campaign_line('{"priceCents":2000}',6,jsonb_set((SELECT data FROM copy_campaign),'{imported,entries,0,restrictions}','"Confirmar disponibilidade"'),'2026-11-20','{"region":"RN","time":"10:00"}')->>'unitCents')::int=2000,'unreviewed restrictions still prevent discount');
SELECT rotamapa_private.check_imported_campaign(auth.uid(),public.rotamapa_current_portfolio(),jsonb_set(jsonb_set((SELECT data FROM copy_campaign),'{imported,entries,0,priceCents}','1800'),'{imported,entries,0,discountBps}','null'));
SELECT test.rejects((SELECT data FROM copy_campaign)-'copiedFrom','edited import without explicit copy provenance rejected');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{copiedFrom,sourceDate}','"2026-11-19"'),'wrong source day');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{copiedFrom,sourceId}',to_jsonb(repeat('c',64))),'forged source id');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{copiedFrom,sourceDate}','"2026-11-20"'),'same source and destination day');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{copiedFrom,sourceDate}','"2026-02-30"'),'invalid date');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{imported,entries,0,minimum}','0'),'zero minimum');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{imported,entries,0,discountBps}','10001'),'discount above 100 percent');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{imported,entries,0,priceCents}','1800'),'price and percentage together');
SELECT test.rejects(jsonb_set(jsonb_set((SELECT data FROM copy_campaign),'{imported,entries,0,priceCents}','2001'),'{imported,entries,0,discountBps}','null'),'price above actual table');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{imported,entries,0,validTo}','"2026-11-21"'),'tier for wrong date');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{imported,entries,0,productId}','"10000000-0000-4000-8000-000000000002"'),'tier for wrong presentation');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{productId}','"10000000-0000-4000-8000-000000000002"'),'product from other account hidden by RLS');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{imported,sourceHash}',to_jsonb(repeat('c',64))),'wrong source hash');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{imported,entries,0,stock}','"abc"'),'invalid stock');
SELECT test.rejects(jsonb_set((SELECT data FROM copy_campaign),'{imported,entries,0,startTime}','"25:00"'),'invalid time');
SELECT test.rejects(jsonb_set((SELECT data FROM source_campaign),'{imported,entries,0,discountBps}','1500'),'original strict import guards preserved');
SELECT set_config('test.plan','free',false);
SELECT test.rejects((SELECT data FROM copy_campaign),'import plan guard preserved');
SELECT set_config('test.plan','pro',false);
CREATE TEMP TABLE chained_copy AS SELECT jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{id}','"20000000-0000-4000-8000-000000000003"'),'{startDate}','"2026-11-21"'),'{endDate}','"2026-11-21"'),'{imported,entries}',jsonb_build_array(jsonb_set(jsonb_set(data#>'{imported,entries,0}','{validFrom}','"2026-11-21"'),'{validTo}','"2026-11-21"'))),'{copiedFrom}',jsonb_build_object('sourceId','20000000-0000-4000-8000-000000000002','sourceDate','2026-11-20')) AS data FROM copy_campaign;
INSERT INTO public.rotamapa_commerce_items SELECT auth.uid(),public.rotamapa_current_portfolio(),(data->>'id')::uuid,'campaign',data FROM chained_copy;
SELECT test.ensure((SELECT count(*)=3 FROM public.rotamapa_commerce_items WHERE kind='campaign'),'copy of a previously copied campaign supported');
SELECT set_config('test.portfolio','00000000-0000-4000-8000-000000000011',false);
SELECT test.rejects((SELECT data FROM copy_campaign),'another portfolio cannot access original document');
SELECT set_config('test.portfolio','00000000-0000-4000-8000-000000000010',false);
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
SELECT test.rejects((SELECT data FROM copy_campaign),'another account cannot copy original document');
RESET ROLE;
SELECT test.ensure(NOT has_function_privilege('anon','rotamapa_private.check_copied_imported_campaign(uuid,uuid,jsonb)','EXECUTE'),'anonymous execution revoked');
SELECT test.ensure((SELECT NOT prosecdef FROM pg_proc WHERE oid='rotamapa_private.check_copied_imported_campaign(uuid,uuid,jsonb)'::regprocedure),'copied validator is security invoker');
SELECT test.ensure((SELECT count(*)=2 FROM pg_class WHERE oid IN('public.rotamapa_commerce_items'::regclass,'public.rotamapa_library_items'::regclass) AND relrowsecurity),'RLS remains enabled');
SELECT 'Daily copy insertion, edited prices, source integrity, chained copies, dates, stock, region, time, restrictions, source hash, permissions and RLS checks passed' AS result;
